        terms["players.support.meaning.raw"] = ("{0} adalah informasi yang tercatat langsung selama sesi permainan.", "{0} is information recorded directly during the game session.");
        terms["players.support.meaning.raw_coins"] = ("{0} menunjukkan jumlah koin yang tercatat pada bagian permainan ini.", "{0} shows the number of coins recorded for this part of the game.");
        terms["players.support.meaning.raw_points"] = ("{0} menunjukkan poin yang menambah atau mengurangi Poin Kebahagiaan.", "{0} shows points that add to or reduce the Happiness Score.");
        terms["players.support.meaning.raw_rank"] = ("{0} menunjukkan posisi pemain dibandingkan pemain lain.", "{0} shows the player's position compared with other players.");
        terms["players.support.meaning.raw_timeline"] = ("{0} menunjukkan kapan nilai atau kejadian ini muncul dalam urutan permainan.", "{0} shows when this value or event appeared in the game sequence.");
        terms["players.support.meaning.raw_count"] = ("{0} menunjukkan banyaknya benda, pilihan, atau kejadian yang tercatat.", "{0} shows how many items, choices, or events were recorded.");
        terms["players.support.meaning.derived"] = ("{0} adalah hasil perhitungan dari beberapa catatan permainan.", "{0} is calculated from multiple gameplay records.");
        terms["players.support.meaning.growth"] = ("{0} membandingkan kas likuid saat ini dengan modal awal; tabungan dan aset lain tidak termasuk.", "{0} compares current liquid cash with starting capital; savings and other assets are excluded.");
        terms["players.support.meaning.income_mix"] = ("{0} menunjukkan apakah pemasukan berasal dari beberapa sumber atau bergantung pada satu sumber.", "{0} shows whether income came from several sources or depended on one source.");
        terms["players.support.meaning.expense_efficiency"] = ("{0} menunjukkan porsi seluruh koin keluar yang membiayai bahan yang benar-benar dipakai pada pesanan selesai.", "{0} shows the share of all outgoing coins that funded ingredients actually used in completed orders.");
        terms["players.support.meaning.business"] = ("{0} membandingkan hasil pesanan makanan dengan biaya bahan yang dikeluarkan.", "{0} compares meal-order returns with ingredient costs.");
        terms["players.support.meaning.gold_return"] = ("{0} menunjukkan untung atau rugi dari seluruh transaksi emas.", "{0} shows the gain or loss from all gold transactions.");
        terms["players.support.meaning.risk_impact"] = ("{0} menunjukkan seberapa besar risiko memengaruhi kondisi keuangan pemain.", "{0} shows how strongly risk affected the player's finances.");
        terms["players.support.meaning.risk_protection"] = ("{0} menunjukkan seberapa baik asuransi mengurangi dampak risiko.", "{0} shows how effectively insurance reduced risk impact.");
        terms["players.support.meaning.risk_appetite"] = ("{0} menggambarkan kecenderungan pemain menerima risiko selama permainan.", "{0} describes the player's tendency to accept risk during the game.");
        terms["players.support.meaning.debt"] = ("{0} menunjukkan besar saldo pinjaman yang belum lunas dibandingkan kas pemain saat ini.", "{0} shows the outstanding loan balance relative to the player's current cash.");
        terms["players.support.meaning.goals"] = ("{0} menunjukkan seberapa aktif pemain mengejar dan mendanai target finansial.", "{0} shows how actively the player pursued and funded financial goals.");
        terms["players.support.meaning.actions"] = ("{0} menunjukkan porsi aksi yang langsung menghasilkan koin masuk dibandingkan seluruh aksi berjatah.", "{0} shows the share of action-slot actions that directly generated incoming coins.");
        terms["players.support.meaning.orders"] = ("{0} menunjukkan bagian pesanan makanan yang berhasil diselesaikan dari seluruh kesempatan.", "{0} shows the share of meal-order opportunities that were completed.");
        terms["players.support.meaning.planning"] = ("{0} menunjukkan seberapa banyak keputusan yang diarahkan untuk manfaat jangka panjang.", "{0} shows how many decisions were aimed at long-term benefits.");
        terms["players.support.meaning.needs"] = ("{0} membantu melihat keseimbangan pemenuhan kebutuhan dan pencapaian misi pemain.", "{0} helps show the balance of need fulfillment and mission achievement.");
        terms["players.support.meaning.need_balance"] = ("{0} menunjukkan pemerataan kartu kebutuhan yang dimiliki antara tingkat primer, sekunder, dan tersier.", "{0} shows how evenly owned need cards are distributed across primary, secondary, and tertiary tiers.");
        terms["players.support.meaning.donation"] = ("{0} menggambarkan jumlah, keteraturan, atau komitmen donasi pemain.", "{0} describes the amount, consistency, or commitment of the player's donations.");
        terms["players.support.meaning.baseline"] = ("{0} berfungsi sebagai titik awal untuk mengukur perubahan kondisi keuangan pemain.", "{0} is the baseline used to measure changes in the player's financial condition.");
        terms["players.support.meaning.income"] = ("{0} berfungsi mengukur kemampuan pemain menghasilkan uang selama permainan.", "{0} measures the player's ability to generate money during the game.");
        terms["players.support.meaning.spending"] = ("{0} berfungsi mengukur beban pengeluaran dan penggunaan uang pemain.", "{0} measures the player's spending load and use of money.");
        terms["players.support.meaning.cash_position"] = ("{0} berfungsi menunjukkan uang yang masih tersedia setelah aktivitas permainan.", "{0} shows the money still available after gameplay activities.");
        terms["players.support.meaning.savings"] = ("{0} berfungsi mengukur dana yang sengaja disisihkan untuk tabungan atau target keuangan.", "{0} measures funds intentionally set aside for savings or financial goals.");
        terms["players.support.meaning.inventory"] = ("{0} berfungsi menilai ketersediaan serta efisiensi penggunaan persediaan bahan.", "{0} assesses ingredient availability and inventory-use efficiency.");
        terms["players.support.meaning.business_activity"] = ("{0} berfungsi menilai kemampuan pemain mengubah bahan dan kesempatan pesanan menjadi pendapatan.", "{0} assesses the player's ability to turn ingredients and order opportunities into income.");
        terms["players.support.meaning.gold_investment"] = ("{0} berfungsi menilai hasil keputusan membeli, menyimpan, dan menjual emas.", "{0} assesses the outcome of buying, holding, and selling gold.");
        terms["players.support.meaning.pension"] = ("{0} berfungsi mengukur kekuatan aset yang disiapkan pemain untuk hasil akhir permainan.", "{0} measures the strength of assets prepared for the player's end-game outcome.");
        terms["players.support.meaning.risk"] = ("{0} berfungsi menilai paparan kerugian dan perlindungan yang digunakan pemain.", "{0} assesses loss exposure and the protection used by the player.");
        terms["players.support.meaning.timeline"] = ("{0} berfungsi melacak kapan dan bagaimana keputusan pemain terjadi dalam urutan permainan.", "{0} tracks when and how the player's decisions occurred in the game sequence.");
        terms["players.support.meaning.outcome"] = ("{0} berfungsi menunjukkan hasil akhir atau status pencapaian pemain.", "{0} shows the player's final outcome or achievement status.");
        terms["players.support.meaning.session_context"] = ("{0} berfungsi memastikan data terhubung ke sesi, pemain, dan waktu perhitungan yang benar.", "{0} ensures the data is tied to the correct session, player, and calculation time.");
        terms["players.support.guide.not_applicable"] = ("Variabel ini hanya digunakan pada mode mahir, sehingga tidak dinilai pada sesi ini.", "This variable is only used in advanced mode, so it is not evaluated in this session.");
        terms["players.support.guide.unavailable"] = ("Belum ada catatan yang cukup untuk menghasilkan nilai ini. Jangan menganggapnya sebagai nol.", "There are not enough records to produce this value. Do not treat it as zero.");
        terms["players.support.guide.coins"] = ("Baca sebagai jumlah koin nyata, bukan sebagai Poin Kebahagiaan.", "Read this as actual coins, not as Happiness Score points.");
        terms["players.support.guide.points"] = ("Baca sebagai bagian dari Poin Kebahagiaan; nilai negatif berarti pengurangan.", "Read this as part of the Happiness Score; a negative value is a deduction.");
        terms["players.support.guide.rank"] = ("Peringkat 1 adalah posisi tertinggi. Angka yang lebih besar berarti posisi lebih rendah.", "Rank 1 is the highest position. A larger number means a lower position.");
        terms["players.support.guide.turn"] = ("Gunakan angka ini untuk menemukan waktu kejadian pada urutan giliran atau slot aksi.", "Use this number to locate the event in the turn or action-slot sequence.");
        terms["players.support.guide.count"] = ("Nilai nol berarti tidak ada kejadian atau benda yang tercatat, bukan data yang hilang.", "Zero means no event or item was recorded; it does not mean the data is missing.");
        terms["players.support.guide.raw"] = ("Baca bersama variabel lain dalam kelompok yang sama untuk memahami konteksnya.", "Read this together with other variables in the same group for context.");
        terms["players.support.guide.percent"] = ("Gunakan rentang 0–100%. Nilai yang lebih tinggi tidak selalu lebih baik; perhatikan arti variabelnya.", "Use the 0–100% range. A higher value is not always better; consider what the variable means.");
        terms["players.support.guide.ratio"] = ("Ini adalah nilai perbandingan. Baca bersama komponen pembentuknya, bukan sebagai jumlah benda.", "This is a comparison value. Read it with its components, not as an item count.");
        terms["players.support.guide.derived"] = ("Gunakan sebagai petunjuk pola, lalu periksa data permainan yang menjadi sumbernya.", "Use this as a pattern indicator, then check the gameplay data behind it.");
        terms["players.support.guide.baseline"] = ("Bandingkan nilai ini dengan uang akhir untuk melihat apakah posisi keuangan bertumbuh atau menyusut.", "Compare this with ending money to see whether the financial position grew or shrank.");
        terms["players.support.guide.income"] = ("Bandingkan dengan total pengeluaran. Nilai yang lebih besar daripada pengeluaran menghasilkan arus kas positif.", "Compare it with total spending. A value above spending produces positive cash flow.");
        terms["players.support.guide.spending"] = ("Bandingkan dengan total pemasukan dan periksa komponen terbesarnya untuk menemukan sumber tekanan kas.", "Compare it with total income and inspect its largest components to find cash-pressure sources.");
        terms["players.support.guide.cash_position"] = ("Bandingkan dengan uang awal; selisih positif berarti pemain menutup permainan dengan posisi kas yang lebih kuat.", "Compare it with starting money; a positive difference means the player ended with a stronger cash position.");
        terms["players.support.guide.savings"] = ("Bandingkan dengan uang awal dan saldo yang masih dipegang untuk melihat porsi dana yang benar-benar diamankan.", "Compare it with starting money and cash still held to see the share of funds actually secured.");
        terms["players.support.guide.inventory"] = ("Baca bersama bahan terkumpul, digunakan, tersisa, dan terbuang untuk menilai apakah persediaan dimanfaatkan secara efisien.", "Read collected, used, remaining, and wasted ingredients together to assess inventory efficiency.");
        terms["players.support.guide.business_activity"] = ("Bandingkan pesanan selesai dan pendapatannya dengan pesanan terlewat serta biaya bahan untuk menilai hasil usaha.", "Compare completed orders and their income with missed orders and ingredient costs to assess business performance.");
        terms["players.support.guide.needs"] = ("Gunakan untuk memeriksa apakah belanja kebutuhan mendukung pemenuhan kebutuhan primer dan penyelesaian misi.", "Use it to check whether need spending supported primary-need fulfillment and mission completion.");
        terms["players.support.guide.donation"] = ("Baca bersama total koin, frekuensi, peringkat, dan poin donasi untuk menilai dampaknya pada kas serta kebahagiaan.", "Read total coins, frequency, rank, and donation points together to assess the impact on cash and happiness.");
        terms["players.support.guide.gold_investment"] = ("Bandingkan koin pembelian, hasil penjualan, dan nilai bersih untuk menentukan apakah transaksi emas untung atau rugi.", "Compare purchase coins, sale proceeds, and net value to determine whether gold trading gained or lost money.");
        terms["players.support.guide.pension"] = ("Gabungkan sisa koin, nilai bahan, dan tabungan; total yang lebih besar menunjukkan cadangan akhir yang lebih kuat.", "Combine remaining cash, ingredient value, and savings; a larger total indicates a stronger end-game reserve.");
        terms["players.support.guide.risk"] = ("Bandingkan risiko yang diterima, biaya yang timbul, dan perlindungan yang digunakan untuk menilai efektivitas mitigasi.", "Compare accepted risks, resulting costs, and protection used to assess mitigation effectiveness.");
        terms["players.support.guide.goals"] = ("Bandingkan target yang tersedia, dicoba, diselesaikan, dan dana yang ditanam untuk menilai keberhasilan perencanaan.", "Compare available, attempted, and completed goals with invested funds to assess planning success.");
        terms["players.support.guide.debt"] = ("Baca jumlah pinjaman, pelunasan, saldo tersisa, dan penalti bersama-sama untuk menilai beban utang akhir.", "Read loan count, repayments, remaining balance, and penalties together to assess the final debt burden.");
        terms["players.support.guide.timeline"] = ("Gunakan slot aksi atau giliran ini untuk menemukan keputusan terkait pada urutan aktivitas pemain.", "Use this action slot or turn to locate the related decision in the player's activity sequence.");
        terms["players.support.guide.outcome"] = ("Gunakan nilai ini untuk memastikan apakah strategi pemain menghasilkan penyelesaian permainan, peringkat, dan poin akhir yang diharapkan.", "Use this value to verify whether the player's strategy produced the expected completion, rank, and final points.");
        terms["players.support.guide.session_context"] = ("Gunakan sebagai identitas audit saat mencocokkan hasil analisis dengan sesi atau aktivitas sumbernya.", "Use it as an audit identity when matching analysis results to their source session or activity.");
        terms["players.support.recommendation.not_applicable"] = ("Sebaiknya jangan menilai keputusan pemain dari data ini karena tidak digunakan pada mode sesi tersebut.", "Do not assess the player's decisions from this data because it is not used in this session mode.");
        terms["players.support.recommendation.unavailable"] = ("Sebaiknya lengkapi catatan permainan terlebih dahulu sebelum menarik kesimpulan finansial.", "Complete the gameplay records before drawing a financial conclusion.");
        terms["players.support.recommendation.baseline"] = ("Sebaiknya modal awal dipakai sebagai pembanding, bukan target; hasil yang sehat menjaga kebutuhan tetap terpenuhi sambil mempertahankan atau menambah nilai akhirnya.", "Use starting capital as a comparison, not a target; a healthy result meets needs while preserving or increasing ending value.");
        terms["players.support.recommendation.income"] = ("Sebaiknya pemasukan lebih besar daripada pengeluaran, cukup konsisten, dan tidak bergantung pada satu sumber saja.", "Income should exceed spending, remain reasonably consistent, and avoid relying on only one source.");
        terms["players.support.recommendation.income_mix"] = ("Sebaiknya pemasukan berasal dari beberapa sumber yang benar-benar aktif agar gangguan pada satu sumber tidak langsung menghentikan arus kas.", "Income should come from several genuinely active sources so a disruption to one source does not stop cash flow.");
        terms["players.support.recommendation.spending"] = ("Sebaiknya pengeluaran tidak melebihi pemasukan dan didahulukan untuk kebutuhan primer, kewajiban, serta aktivitas yang menghasilkan manfaat.", "Spending should stay below income and prioritize primary needs, obligations, and activities that create value.");
        terms["players.support.recommendation.cash_position"] = ("Sebaiknya saldo akhir tetap positif, lebih kuat daripada posisi awal, dan tidak dibentuk oleh pinjaman yang belum lunas.", "Ending cash should remain positive, improve on the starting position, and not be supported by unpaid debt.");
        terms["players.support.recommendation.savings"] = ("Sebaiknya tabungan disisihkan secara konsisten setelah kebutuhan primer terpenuhi, tanpa menambah utang untuk menutup pengeluaran rutin.", "Savings should be set aside consistently after primary needs are met, without adding debt to cover routine spending.");
        terms["players.support.recommendation.inventory"] = ("Sebaiknya persediaan cukup untuk mendukung pesanan, cepat digunakan, dan menyisakan bahan terbuang sesedikit mungkin.", "Inventory should be sufficient for orders, used promptly, and produce as little waste as possible.");
        terms["players.support.recommendation.business_activity"] = ("Sebaiknya pendapatan pesanan melampaui seluruh biaya bahan; pertumbuhan penjualan tidak dianggap sehat bila margin masih negatif.", "Order income should exceed all ingredient costs; sales growth is not healthy while margins remain negative.");
        terms["players.support.recommendation.needs"] = ("Sebaiknya kebutuhan primer dipenuhi lebih dahulu; kebutuhan sekunder dan tersier dipilih setelah arus kas serta kewajiban utama aman.", "Primary needs should be met first; secondary and tertiary needs should follow after cash flow and core obligations are secure.");
        terms["players.support.recommendation.donation"] = ("Sebaiknya donasi dilakukan terencana dan konsisten sesuai kemampuan, tanpa mengorbankan kebutuhan primer, tabungan, atau pelunasan kewajiban.", "Donations should be planned and consistent within one's means, without sacrificing primary needs, savings, or debt repayment.");
        terms["players.support.recommendation.gold_investment"] = ("Sebaiknya emas digunakan untuk diversifikasi setelah dana likuid tersedia; keputusan dinilai baik bila hasil bersih positif setelah seluruh biaya.", "Gold should diversify finances after liquid funds are available; the decision is favorable when net returns remain positive after all costs.");
        terms["players.support.recommendation.pension"] = ("Sebaiknya dana jangka panjang dibangun dari surplus secara bertahap dan tidak hanya bergantung pada satu jenis aset.", "Long-term funds should be built gradually from surplus and not rely on a single asset type.");
        terms["players.support.recommendation.risk"] = ("Sebaiknya risiko diterima hanya ketika manfaatnya sepadan, potensi kerugian masih terjangkau, dan perlindungan telah disiapkan.", "Risk should be accepted only when potential benefits are proportionate, possible losses remain affordable, and protection is prepared.");
        terms["players.support.recommendation.protection"] = ("Sebaiknya perlindungan menutup risiko utama dengan biaya yang tetap terjangkau; perlindungan bukan alasan untuk mengambil risiko berlebihan.", "Protection should cover major risks at an affordable cost; coverage is not a reason to take excessive risk.");
        terms["players.support.recommendation.goals"] = ("Sebaiknya target finansial dibuat jelas, didanai bertahap, dan disesuaikan dengan kemampuan agar dana tidak hangus karena target ditinggalkan.", "Financial goals should be clear, funded gradually, and matched to capacity so money is not lost on abandoned goals.");
        terms["players.support.recommendation.debt"] = ("Sebaiknya pinjaman dipakai terbatas untuk kebutuhan penting atau produktif, cicilannya terjangkau, dan dilunasi tepat waktu.", "Debt should be limited to important or productive needs, remain affordable to repay, and be cleared on time.");
        terms["players.support.recommendation.timeline"] = ("Sebaiknya keputusan mengikuti urutan prioritas: kebutuhan primer, cadangan kas, penghasilan, kewajiban, lalu target dan investasi.", "Decisions should follow this priority: primary needs, cash reserves, income, obligations, then goals and investments.");
        terms["players.support.recommendation.planning"] = ("Sebaiknya keputusan jangka panjang tetap mendapat porsi setelah kebutuhan saat ini dan cadangan kas aman, sehingga tujuan masa depan tidak mengganggu kestabilan hari ini.", "Long-term decisions should receive a share after current needs and cash reserves are secure, so future goals do not disrupt today's stability.");
        terms["players.support.recommendation.outcome"] = ("Sebaiknya hasil akhir dinilai secara seimbang; poin tinggi belum tentu sehat bila kas habis, kebutuhan terlewat, atau kewajiban belum selesai.", "Final results should be judged in balance; a high score is not necessarily healthy if cash is depleted, needs are missed, or obligations remain.");
        terms["players.support.recommendation.session_context"] = ("Sebaiknya data konteks hanya dipakai untuk memvalidasi sumber, bukan untuk menilai kemampuan finansial pemain.", "Context data should only validate the source, not assess the player's financial ability.");
        terms["players.support.recommendation.wealth"] = ("Pertahankan kas di atas modal awal setelah kebutuhan dan kewajiban terpenuhi, lalu baca tabungan serta aset secara terpisah untuk menilai kekayaan keseluruhan.", "Keep cash above starting capital after needs and obligations are met, then review savings and assets separately to assess overall wealth.");
        terms["players.support.recommendation.cash_recover"] = ("Kas saat ini berada di bawah modal awal. Tinjau pengeluaran terbesar dan pulihkan surplus tanpa mengandalkan pinjaman yang belum lunas.", "Current cash is below starting capital. Review the largest outflows and restore a surplus without relying on unpaid loans.");
        terms["players.support.recommendation.income_mix_recover"] = ("Pemasukan masih terkonsentrasi. Aktifkan sumber pendapatan lain yang layak agar arus kas tidak bergantung pada satu aktivitas.", "Income remains concentrated. Activate other viable income sources so cash flow does not depend on one activity.");
        terms["players.support.recommendation.productive_spending"] = ("Baca porsi ini bersama margin usaha, tabungan, dan kewajiban. Porsi bahan terpakai yang besar hanya sehat bila pesanan tetap menghasilkan laba.", "Read this share with business margin, savings, and obligations. A large used-ingredient share is healthy only when orders remain profitable.");
        terms["players.support.recommendation.business_recover"] = ("Pendapatan pesanan belum menutup seluruh investasi bahan. Kurangi bahan menganggur atau tingkatkan penyelesaian pesanan sebelum menambah investasi.", "Order income has not covered all ingredient investment. Reduce idle ingredients or improve order completion before investing more.");
        terms["players.support.recommendation.risk_reduce"] = ("Penerimaan dan biaya risiko sama-sama tinggi. Kurangi risiko berbiaya besar dan siapkan perlindungan sebelum mengambil risiko berikutnya.", "Risk acceptance and cost are both high. Reduce high-cost risks and prepare protection before taking the next risk.");
        terms["players.support.recommendation.debt_reduce"] = ("Saldo pinjaman tinggi dibandingkan kas. Dahulukan pelunasan dan hindari pinjaman baru sampai beban kembali terjangkau.", "Outstanding loans are high relative to cash. Prioritize repayment and avoid new borrowing until the burden is affordable again.");
        terms["players.support.recommendation.goals_focus"] = ("Pengejaran target masih terbatas. Pilih target yang paling realistis dan danai secara bertahap agar tidak banyak target berhenti di tengah jalan.", "Goal pursuit remains limited. Choose the most realistic goal and fund it gradually so fewer goals are abandoned midway.");
        terms["players.support.recommendation.action_income"] = ("Porsi aksi penghasil pemasukan masih rendah. Tambahkan aksi pemasukan bila kas belum aman, tanpa mengabaikan kebutuhan dan kewajiban.", "The share of income-producing actions remains low. Add income actions when cash is not yet secure without neglecting needs and obligations.");
        terms["players.support.recommendation.action_balance"] = ("Pertahankan aksi pemasukan secukupnya sambil menyisakan jatah untuk kebutuhan, kewajiban, dan tujuan jangka panjang.", "Maintain enough income actions while preserving action slots for needs, obligations, and long-term goals.");
        terms["players.support.recommendation.orders_improve"] = ("Banyak kesempatan pesanan belum selesai. Cocokkan pembelian bahan dengan kebutuhan pesanan sebelum mengambil kesempatan berikutnya.", "Many order opportunities were not completed. Match ingredient purchases to order requirements before taking the next opportunity.");
        terms["players.support.recommendation.planning_build"] = ("Porsi aksi jangka panjang masih rendah. Sisihkan aksi untuk tabungan, target finansial, atau premi setelah kas dan kebutuhan saat ini aman.", "The share of long-term actions remains low. Allocate actions to savings, financial goals, or premiums after current cash and needs are secure.");
        terms["players.support.recommendation.needs_balance"] = ("Kepemilikan kebutuhan masih terkonsentrasi pada satu tingkat. Seimbangkan tingkat yang tertinggal setelah kebutuhan primer dan kas aman.", "Need ownership remains concentrated in one tier. Balance the lagging tier after primary needs and cash are secure.");
        terms["players.support.recommendation.donation_stabilize"] = ("Komitmen donasi masih rendah. Gunakan nominal yang lebih konsisten dan sesuai kemampuan pada kesempatan Jumat berikutnya.", "Donation commitment remains low. Use a more consistent and affordable amount at the next Friday opportunity.");
        terms["players.support.recommendation.outcome_recover"] = ("Total Poin Kebahagiaan negatif. Periksa penalti misi dan pinjaman lebih dahulu sebelum mengejar sumber poin tambahan.", "Total Happiness Points are negative. Address mission and loan penalties before pursuing additional point sources.");
        terms["players.support.recommendation.balance"] = ("Sebaiknya hasil ini tidak dinilai sendirian; cocokkan dengan arus kas, kebutuhan primer, risiko, dan kewajiban sebelum mengambil kesimpulan.", "Do not judge this result alone; compare it with cash flow, primary needs, risk, and obligations before concluding.");
        terms["players.support.guide.wealth_exceptional"] = ("Di atas 300%: kas saat ini lebih dari tiga kali modal awal.", "Above 300%: current cash is more than three times starting capital.");
        terms["players.support.guide.wealth_strong"] = ("200–300%: kas saat ini tumbuh kuat dibandingkan modal awal.", "200–300%: current cash grew strongly compared with starting capital.");
        terms["players.support.guide.wealth_growing"] = ("100–200%: kas saat ini lebih besar daripada modal awal.", "100–200%: current cash is higher than starting capital.");
        terms["players.support.guide.wealth_declining"] = ("Di bawah 100%: kas saat ini lebih kecil daripada modal awal.", "Below 100%: current cash is lower than starting capital.");
        terms["players.support.guide.income_diverse"] = ("Pemasukan cukup tersebar di beberapa sumber sehingga tidak bergantung pada satu aktivitas.", "Income is spread across several sources and does not depend on one activity.");
        terms["players.support.guide.income_mixed"] = ("Pemasukan mulai tersebar, tetapi satu atau dua sumber masih memberi kontribusi utama.", "Income has started to diversify, but one or two sources still provide the main contribution.");
        terms["players.support.guide.income_concentrated"] = ("Pemasukan masih bergantung pada sedikit sumber. Periksa sumber pendapatan terbesarnya.", "Income still depends on few sources. Check the largest income source.");
        terms["players.support.guide.expense_efficiency"] = ("Nilai ini adalah porsi, bukan penilaian baik atau buruk. Cocokkan dengan margin usaha untuk memastikan bahan terpakai benar-benar menghasilkan laba.", "This value is a share, not a good-or-bad rating. Compare it with business margin to confirm that used ingredients actually produced profit.");
        terms["players.support.guide.return_positive"] = ("Nilai positif berarti kegiatan ini menghasilkan keuntungan.", "A positive value means this activity produced a gain.");
        terms["players.support.guide.return_negative"] = ("Nilai negatif berarti biaya lebih besar daripada hasil yang diterima.", "A negative value means costs were higher than returns.");
        terms["players.support.guide.return_even"] = ("Nilai nol berarti tidak ada keuntungan maupun kerugian bersih.", "Zero means there was no net gain or loss.");
        terms["players.support.guide.business_efficient"] = ("Di atas 2: setiap koin biaya bahan menghasilkan lebih dari dua koin pendapatan.", "Above 2: each coin spent on ingredients produced more than two coins of income.");
        terms["players.support.guide.business_inefficient"] = ("Di bawah 1,5: hasil pesanan masih rendah dibandingkan biaya bahan.", "Below 1.5: order returns are still low compared with ingredient costs.");
        terms["players.support.guide.business_moderate"] = ("Antara 1,5–2: usaha menghasilkan pemasukan, tetapi efisiensinya masih sedang.", "Between 1.5–2: the business generated income, but efficiency is still moderate.");
        terms["players.support.guide.risk_high"] = ("Di atas 30%: biaya risiko mengambil bagian besar dari pemasukan.", "Above 30%: risk costs consumed a large share of income.");
        terms["players.support.guide.risk_low"] = ("Di bawah 10%: dampak biaya risiko terhadap pemasukan relatif kecil.", "Below 10%: risk costs had a relatively small impact on income.");
        terms["players.support.guide.risk_moderate"] = ("10–30%: dampak risiko berada pada tingkat menengah.", "10–30%: risk impact is at a moderate level.");
        terms["players.support.guide.appetite_cautious"] = ("0–25: gabungan frekuensi penerimaan dan biaya risiko relatif rendah.", "0–25: the combination of acceptance frequency and risk cost is relatively low.");
        terms["players.support.guide.appetite_balanced"] = ("25–75: gabungan frekuensi penerimaan dan biaya risiko berada pada tingkat menengah.", "25–75: the combination of acceptance frequency and risk cost is moderate.");
        terms["players.support.guide.appetite_high"] = ("Di atas 75: pemain sering menerima risiko berbiaya besar dibandingkan modal awal.", "Above 75: the player often accepted risks with high costs relative to starting capital.");
        terms["players.support.guide.debt_low"] = ("0–25%: penggunaan utang relatif rendah dibandingkan kondisi keuangan pemain.", "0–25%: debt usage is relatively low compared with the player's finances.");
        terms["players.support.guide.debt_moderate"] = ("25–75%: pinjaman digunakan dalam tingkat menengah dan perlu dipantau bersama pelunasannya.", "25–75%: loans were used at a moderate level and should be reviewed with repayment.");
        terms["players.support.guide.debt_high"] = ("Di atas 75%: beban pinjaman tinggi dibandingkan kondisi keuangan pemain.", "Above 75%: the loan burden is high compared with the player's finances.");
        terms["players.support.guide.goals_strong"] = ("67% atau lebih: pemain aktif mengejar target dan mengalokasikan dana untuk mencapainya.", "67% or more: the player actively pursued goals and allocated funds toward them.");
        terms["players.support.guide.goals_moderate"] = ("34–67%: target mulai dikejar, tetapi percobaan atau pendanaannya masih sedang.", "34–67%: goals were pursued, but attempts or funding remained moderate.");
        terms["players.support.guide.goals_limited"] = ("Di bawah 34%: hanya sedikit target yang dicoba atau didanai.", "Below 34%: few goals were attempted or funded.");
        terms["players.support.guide.loan_repaid"] = ("Mendekati 100% berarti seluruh pinjaman berhasil dilunasi.", "Close to 100% means all loans were successfully repaid.");
        terms["players.support.guide.loan_remaining"] = ("Di bawah 100% berarti masih ada pinjaman yang belum sepenuhnya dilunasi.", "Below 100% means some loans were not fully repaid.");
        terms["players.support.guide.action_income"] = ("Di atas 60%: sebagian besar aksi diarahkan untuk membangun pemasukan.", "Above 60%: most actions were directed toward building income.");
        terms["players.support.guide.action_exploration"] = ("Di bawah 40%: sebagian besar aksi digunakan untuk kegiatan yang tidak langsung menghasilkan koin masuk.", "Below 40%: most actions were used for activities that did not directly generate incoming coins.");
        terms["players.support.guide.action_balanced"] = ("40–60%: aksi pemasukan dan aksi lainnya relatif seimbang.", "40–60%: income actions and other actions were relatively balanced.");
